import logging
import time
from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core.entities.named import NamedComponent

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class DockerContainer(Using("tool_executor"),
                      NamedComponent):
    """
    Setup docker container for sherpa converter usage
    """

    def __init__(self,
                 sherpa_image='sherpa_latest',
                 docker_port1=7080,
                 docker_port2=7900,
                 docker_v1_mount='/dev/shm1:/dev/shm',
                 sherpa_licence='/root/license.lic',
                 tool_licence_path='/home/ubuntu/.config/NOKIA/Sherpa5G_18/',
                 container_start_timeout=60,
                 **kwargs):
        super(DockerContainer, self).__init__(**kwargs)
        for parameter_name, parameter_value in locals().items():
            if parameter_name not in ("self", "kwargs"):
                setattr(self, "_" + parameter_name, parameter_value)
        self._executor_dir = '/tmp/SherpaLogs_{name}'.format(name=self.name)
        self._sudo_prefix = ''
        self._docker_prefix = ''

    @property
    def docker_prefix(self):
        return self._docker_prefix

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._setup_docker_and_get_container_id()
        self._tool_executor.execute('mkdir -p {executor_dir}'.format(executor_dir=self._executor_dir).encode())

    def _teardown(self):
        self._tool_executor.execute('{_sudo_prefix}rm -r {_executor_dir}'.format(**self.__dict__).encode())
        self._tool_executor.execute('{_sudo_prefix}docker stop {_container_id}'.format(**self.__dict__).encode())

    def _setup_docker_and_get_container_id(self):
        container_id_command = '{_sudo_prefix}docker ps --filter ancestor={_sherpa_image}'.format(**self.__dict__)
        existing_container_id = self._tool_executor.execute((container_id_command + ' -q').encode()).decode()
        if existing_container_id != '':
            self._tool_executor.execute(
                ('{sudo_prefix}docker stop $(' + container_id_command + ' -q)').format(
                    sudo_prefix=self._sudo_prefix).encode())
        self._tool_executor.execute(
            '{_sudo_prefix}docker run -p {_docker_port1}:80 -p {_docker_port2}:5900 '
            '-v {_docker_v1_mount} -v /tmp:/tmp '
            '{_sherpa_image} > /tmp/docker.log 2>/tmp/docker_error.log &'.format(**self.__dict__).encode())
        timeout = self._container_start_timeout
        while (b'(healthy)' not in self._tool_executor.execute(container_id_command.encode())) \
                and (timeout > 0):
            time.sleep(1)
            timeout -= 1
        if timeout <= 0:
            raise RuntimeError("Failed to start sherpa container in {} seconds. Please check /tmp/docker.log and"
                               " /tmp/docker_error.log".format(self._container_start_timeout))
        self._container_id = self._tool_executor.execute((container_id_command + ' -q').encode()).decode().split()[0]
        self._docker_prefix = 'docker exec --tty {container_id} '.format(container_id=self._container_id)
        self._tool_executor.execute(
            '{_sudo_prefix}{_docker_prefix}'
            'cp {_sherpa_licence} {_tool_licence_path}Sherpa5G.lic'.format(**self.__dict__).encode())
